create policy "post authors delete comments" on public.activity_comments
  as permissive
  for delete
  to public
  using ((EXISTS ( SELECT 1
   FROM public.activity_posts p
  WHERE p.id = activity_comments.post_id AND p.author_id = (( SELECT auth.uid() AS uid)))));
